import React,{useState}from'react';import{createRoot}from'react-dom/client';import{TestAuthContext,initialAuth}from'./data-provider-integrity-mocks';import{useWorkshopActivities}from'../../utils/useWorkshopActivities';
let api:any,configure:any,actor:string;function Probe(){api=useWorkshopActivities();return <pre>{JSON.stringify({ready:api?.ready,pending:api?.pending,error:api?.error,activities:api?.activities})}</pre>}function Harness(){const[auth,setAuth]=useState(initialAuth);actor=auth.session.user.id;configure=(actor:string)=>setAuth({session:{user:{id:actor},access_token:actor},sedeId:actor==='owner-a'?'sede-a':'sede-b',isSuperAdmin:false});return <TestAuthContext.Provider value={auth}><Probe/></TestAuthContext.Provider>};(window as any).__agenda={configure:(actor:string)=>configure(actor),snapshot:()=>({actor,ready:api.ready,pending:api.pending,error:api.error,activities:api.activities}),save:async()=>{try{await api.save({title:'Test',date:'2026-11-18',time:'16:00',endTime:'17:00',description:''});return{ok:true}}catch(e:any){return{ok:false,error:e.message}}},retry:async()=>{try{await api.retry();return{ok:true}}catch(e:any){return{ok:false,error:e.message}}}};createRoot(document.getElementById('root')!).render(<Harness/>);